def next_smallest_palindrome(n: int) -> int:
    """Return the smallest palindrome strictly greater than n."""
    # Single-digit inputs: the next integer is the next palindrome.
    if n < 9:
        return n + 1

    s = str(n)
    length = len(s)
    half_len = (length + 1) // 2
    left = int(s[:half_len])

    def build(h: int) -> int:
        h_str = str(h)
        if length % 2 == 0:
            return int(h_str + h_str[::-1])
        # Odd length: middle digit is the last digit of the half.
        return int(h_str + h_str[-2::-1])

    # Mirroring the current left half may already exceed n.
    candidate = build(left)
    if candidate > n:
        return candidate

    # Otherwise increment the left half and mirror again.
    left += 1
    if len(str(left)) > half_len:
        # All-9s case (e.g., 99 -> 101, 999 -> 1001).
        return 10 ** length + 1
    return build(left)
