def amicable_numbers_sum(n):
    def proper_divisor_sum(x):
        if x <= 1:
            return 0
        total = 1
        for i in range(2, int(x ** 0.5) + 1):
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
        return total

    total = 0
    for num in range(2, n + 1):
        s = proper_divisor_sum(num)
        if s != num and proper_divisor_sum(s) == num:
            total += num
    return total
