def max_sub_array_sum_repeated(arr, n, k):
    def kadane(a):
        best = float('-inf')
        cur = 0
        for x in a:
            cur = max(x, cur + x)
            if cur > best:
                best = cur
        return best

    arr = arr[:n]
    if k == 1:
        return kadane(arr)

    total = sum(arr)
    max_two = kadane(arr + arr)

    if total > 0:
        return max_two + (k - 2) * total
    return max_two
