def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0.0

    # Every path from top-left to bottom-right (moving only right/down)
    # visits exactly 2*n - 1 cells, so maximizing the average is
    # equivalent to maximizing the total cost of the path.
    dp = [0] * n
    dp[0] = matrix[0][0]

    for j in range(1, n):
        dp[j] = dp[j - 1] + matrix[0][j]

    for i in range(1, n):
        dp[0] += matrix[i][0]
        for j in range(1, n):
            dp[j] = max(dp[j], dp[j - 1]) + matrix[i][j]

    return dp[n - 1] / (2 * n - 1)
```

