The failing test reveals that when keys conflict, the value from the **earlier** dictionary must win (`"B": "Black"` from dict1 beats `"B": "Blue"` from dict3), not the later one. The fix is to keep the first occurrence of each key instead of overwriting.

```python
def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merge three dictionaries into a single new dictionary.

    - The input dictionaries are not modified (a new dict is built).
    - If the same key appears in more than one dictionary, the value
      from the EARLIER dictionary takes precedence (first occurrence
      wins), as required by the tests.
    - Empty dictionaries are handled naturally; if all three are empty,
      an empty dictionary is returned.
    - Works with any hashable keys and any values.
    """
    merged = {}
    for d in (dict1, dict2, dict3):
        for key, value in d.items():
            if key not in merged:
                merged[key] = value
    return merged


if __name__ == "__main__":
    # Original test (conflicts have identical values, so order is ambiguous)
    assert merge_dictionaries_three(
        {"R": "Red", "B": "Black", "P": "Pink"},
        {"G": "Green", "W": "White"},
        {"O": "Orange", "W": "White", "B": "Black"},
    ) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

    # Previously failing test: first dictionary wins on key conflicts
    assert merge_dictionaries_three(
        {"R": "Red", "B": "Black", "P": "Pink"},
        {"G": "Green", "W": "White"},
        {"L": "lavender", "B": "Blue"},
    ) == {'W': 'White', 'P': 'Pink', 'B': 'Black', 'R': 'Red', 'G': 'Green', 'L': 'lavender'}

    # Edge cases
    assert merge_dictionaries_three({}, {}, {}) == {}
    assert merge_dictionaries_three({"a": 1}, {}, {"a": 2}) == {"a": 1}  # earlier wins
    first = {"x": 1}
    merge_dictionaries_three(first, {"y": 2}, {})
    assert first == {"x": 1}  # inputs are not mutated
    print("All tests passed.")
