def is_undulating(n):
    s = str(abs(n))
    if len(s) < 3:
        return False
    a, b = s[0], s[1]
    if a == b:
        return False
    for i, ch in enumerate(s):
        if ch != (a if i % 2 == 0 else b):
            return False
    return True
